package com.eventhub.controller; import com.eventhub.dto.*; import com.eventhub.service.NoticeService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Page; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import jakarta.servlet.http.HttpServletRequest; @RestController @RequestMapping("/api/notices") @RequiredArgsConstructor public class NoticeController {private final NoticeService service; @GetMapping public Page<NoticeResponse> active(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.active(page,size);} @GetMapping("/all") @PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')") public Page<NoticeResponse> all(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return service.all(a.getName(),page,size);} @PostMapping @PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')") public NoticeResponse create(Authentication a,@Valid @RequestBody NoticeRequest r,HttpServletRequest req){return service.create(a.getName(),r,req.getRemoteAddr());} @PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')") public NoticeResponse update(Authentication a,@PathVariable Long id,@Valid @RequestBody NoticeRequest r,HttpServletRequest req){return service.update(a.getName(),id,r,req.getRemoteAddr());} @DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')") public void delete(Authentication a,@PathVariable Long id,HttpServletRequest req){service.delete(a.getName(),id,req.getRemoteAddr());}}
